<script setup>
import { computed, ref } from 'vue'
import events from '../.data/events.json'
const from=ref('2026-09-12'), to=ref('2026-09-20'), area=ref(''), q=ref('')
const areas=computed(()=>[...new Set(events.map(e=>e.area).filter(Boolean))])
const filtered=computed(()=>events.filter(e=>e.date>=from.value&&e.date<=to.value).filter(e=>!area.value||e.area===area.value).filter(e=>!q.value||`${e.title} ${e.venue} ${(e.artists||[]).join(' ')}`.toLowerCase().includes(q.value.toLowerCase())).sort((a,b)=>`${a.date}${a.start_at||''}`.localeCompare(`${b.date}${b.start_at||''}`)))
</script>
<template><main class="container"><header><p class="eyebrow">OWARAI LIVE</p><h1>東京のお笑いLIVE検索</h1><p class="lead">idol-liveのUI思想をそのまま、お笑い版へ。下北GRIP / 下北GRIP DASHは除外。</p></header><section class="filters"><label>開始日<input v-model="from" type="date"></label><label>終了日<input v-model="to" type="date"></label><label>エリア<select v-model="area"><option value="">すべて</option><option v-for="a in areas" :key="a">{{a}}</option></select></label><label>検索<input v-model="q" placeholder="ライブ名・芸人・会場"></label></section><section class="agent"><strong>🔎 Search Agent v1</strong><span>公式情報優先 · 日付正規化 · 重複排除 · GRIP/DASH除外 · 情報源保存</span></section><div class="summary">{{filtered.length}}件 · {{from}}〜{{to}}</div><section class="list"><article v-for="e in filtered" :key="e.id" class="card"><div class="date">{{e.date}}<br><b>{{e.start_at||''}}</b></div><div class="body"><h2>{{e.title}}</h2><p class="artists">{{(e.artists||[]).join(' / ')}}</p><p>📍 {{e.venue}} · {{e.area}}</p><div class="badges"><span class="badge">{{e.price||'料金要確認'}}</span><span class="badge muted">{{e.source_type}}</span><span class="badge muted">{{e.confidence}}</span></div><p class="note">{{e.note}}</p><a :href="e.source_url" target="_blank">情報源 ↗</a></div></article></section><section v-if="!filtered.length" class="empty">該当ライブなし。検索エージェントの探索範囲を広げよう。</section><footer>Excluded: 下北GRIP / 下北GRIP DASH</footer></main></template>
